#include <memory>

struct OrderBook;
OrderBook* create_book(const char* symbol);
void destroy_book(OrderBook*);
int raw_best_bid(const OrderBook*);

struct BookDeleter {
    void operator()(OrderBook* book) const noexcept {
        if (book != nullptr) {
            destroy_book(book);
        }
    }
};

using BookHandle = std::unique_ptr<OrderBook, BookDeleter>;

BookHandle open_book(const char* symbol) {
    return BookHandle{create_book(symbol)};
}

// Downstream code borrows; nothing here can end the book's lifetime.
int best_bid(const OrderBook& book) {
    return raw_best_bid(&book);
}

void use() {
    auto book = open_book("EUR/USD");
    if (book) {
        (void)best_bid(*book);
    }
}

#include <memory>
#include <utility>

struct Config {
    bool passive;
};

struct Strategy {
    virtual ~Strategy() = default;
    virtual int quote() const = 0;
};

struct PassiveStrategy final : Strategy {
    int quote() const override { return 101; }
};

struct AggressiveStrategy final : Strategy {
    int quote() const override { return 102; }
};

std::unique_ptr<Strategy> make_strategy(const Config& config) {
    if (config.passive) {
        return std::make_unique<PassiveStrategy>();
    }
    return std::make_unique<AggressiveStrategy>();
}

void inspect(const Strategy& strategy) {
    (void)strategy.quote();
}

struct Engine {
    std::unique_ptr<Strategy> strategy;  // rule of zero
};

void start_engine(std::unique_ptr<Strategy> strategy) {
    Engine engine{std::move(strategy)};
    inspect(*engine.strategy);
}

void configure(const Config& config) {
    auto strategy = make_strategy(config);
    inspect(*strategy);
    start_engine(std::move(strategy));
}

#include <cstdio>
#include <memory>

struct FCloser {
    void operator()(std::FILE* file) const noexcept {
        if (file != nullptr) {
            std::fclose(file);
        }
    }
};

using CompactFile = std::unique_ptr<std::FILE, FCloser>;
using FunctionFile = std::unique_ptr<std::FILE, decltype(&std::fclose)>;

CompactFile open_compact(const char* path) {
    return CompactFile{std::fopen(path, "rb")};
}

FunctionFile open_with_function(const char* path) {
    return FunctionFile{std::fopen(path, "rb"), &std::fclose};
}

static_assert(sizeof(CompactFile) == sizeof(void*));
static_assert(sizeof(FunctionFile) == 2 * sizeof(void*));

#include <iostream>
#include <memory>

struct Child;

struct Parent {
    std::shared_ptr<Child> child;
    int level = 3;
    ~Parent() { std::cout << "~Parent\n"; }
};

struct Child {
    std::weak_ptr<Parent> parent;  // observation, not ownership
    ~Child() { std::cout << "~Child\n"; }

    void report_parent() const {
        // One lock(): the returned owner keeps the parent alive for the
        // whole body, so there is no window between test and use.
        if (auto owner = parent.lock()) {
            std::cout << "parent level " << owner->level << '\n';
        } else {
            std::cout << "parent gone\n";
        }
    }
};

void use_tree() {
    auto parent = std::make_shared<Parent>();
    auto child = std::make_shared<Child>();
    parent->child = child;
    child->parent = parent;
    child->report_parent();
}

#include <memory>

struct Registry;

struct Session : std::enable_shared_from_this<Session> {
    void register_self(Registry& registry);

    // WRONG: a fresh shared_ptr from `this` builds a second control block
    // that knows nothing about the first, so the object is deleted twice.
    //
    //   std::shared_ptr<Session> wrong() {
    //       return std::shared_ptr<Session>(this);
    //   }
};

struct Registry {
    std::shared_ptr<Session> current;
};

void Session::register_self(Registry& registry) {
    // Finds the existing control block. Calling this from a constructor,
    // or on a stack Session, throws std::bad_weak_ptr: no shared_ptr has
    // established ownership yet.
    registry.current = shared_from_this();
}

void connect(Registry& registry) {
    auto session = std::make_shared<Session>();
    session->register_self(registry);
}

#include <cassert>
#include <cstddef>
#include <utility>

class RefCounted {
public:
    void add_ref() noexcept { ++references_; }

    void release() noexcept {
        assert(references_ > 0);
        if (--references_ == 0) {
            delete this;
        }
    }

protected:
    virtual ~RefCounted() = default;

private:
    std::size_t references_ = 0;
};

class OrderBook final : public RefCounted {
public:
    explicit OrderBook(int levels) : levels_(levels) {}
    int levels() const noexcept { return levels_; }

private:
    int levels_;
};

class IntrusiveBookPtr {
public:
    explicit IntrusiveBookPtr(OrderBook* pointer = nullptr)
        : pointer_(pointer) {
        if (pointer_ != nullptr) {
            pointer_->add_ref();
        }
    }

    IntrusiveBookPtr(const IntrusiveBookPtr& other)
        : IntrusiveBookPtr(other.pointer_) {}

    IntrusiveBookPtr(IntrusiveBookPtr&& other) noexcept
        : pointer_(std::exchange(other.pointer_, nullptr)) {}

    ~IntrusiveBookPtr() {
        if (pointer_ != nullptr) {
            pointer_->release();
        }
    }

    OrderBook& operator*() const noexcept { return *pointer_; }
    OrderBook* operator->() const noexcept { return pointer_; }

private:
    OrderBook* pointer_;
};

static_assert(sizeof(IntrusiveBookPtr) == sizeof(void*));

#include <memory>

struct OrderBook {
    int best_bid() const noexcept { return 101; }
    int best_ask() const noexcept { return 102; }
};

// Each helper only reads, so each borrows. No count, no allocation.
int bid(const OrderBook& book) noexcept { return book.best_bid(); }
int ask(const OrderBook& book) noexcept { return book.best_ask(); }
int mid(const OrderBook& book) noexcept { return (bid(book) + ask(book)) / 2; }

// A by-value shared_ptr parameter cost a thread-safe increment at the
// call and a decrement plus a last-owner branch at return, on a cache
// line other cores may also be updating. The handler borrows instead.
int on_tick(const OrderBook& book) noexcept {
    return mid(book);
}

struct Session {
    // Ownership is established once, at session setup, not per tick.
    std::shared_ptr<OrderBook> book = std::make_shared<OrderBook>();

    int tick() noexcept { return on_tick(*book); }
};

#include <array>
#include <memory>

struct Snapshot {
    std::array<char, 1'000'000> bytes{};
};

std::shared_ptr<Snapshot> combined() {
    return std::make_shared<Snapshot>();   // one allocation
}

std::shared_ptr<Snapshot> separate() {
    return std::shared_ptr<Snapshot>(new Snapshot);  // two allocations
}

void walkthrough() {
    std::weak_ptr<Snapshot> observer;

    {
        auto snapshot = combined();
        observer = snapshot;
    }
    // Strong count hit zero: ~Snapshot ran, so the object is DESTROYED.
    // The control block must survive for `observer`, and with make_shared
    // it shares one allocation with the object -- so the whole megabyte is
    // still NOT DEALLOCATED. A profiler shows the block as live.

    observer.reset();
    // Weak count hit zero: the combined allocation is finally released.

    {
        auto snapshot = separate();
        observer = snapshot;
    }
    // Strong count hit zero: destroyed AND the megabyte is deallocated,
    // because the object had its own allocation. Only the small control
    // block is retained for `observer`.

    // Rule: prefer make_shared (one allocation, better locality) unless
    // objects are large AND weak_ptrs routinely outlive every owner.
}
